
-- Unique key so seed is idempotent
ALTER TABLE public.supplier_products
  DROP CONSTRAINT IF EXISTS supplier_products_supplier_extid_key;
ALTER TABLE public.supplier_products
  ADD CONSTRAINT supplier_products_supplier_extid_key
  UNIQUE (supplier_id, supplier_product_id);

WITH g AS (SELECT id FROM public.supplier_profiles WHERE supplier_name = 'Giacom' LIMIT 1)
INSERT INTO public.supplier_products (
  supplier_id, supplier_product_id, product_name, service_type, technology, network,
  download_speed_label, upload_speed_label, download_speed_mbps, upload_speed_mbps,
  min_term_months, supplier_monthly_net, connection_fee_net, etf_applies,
  disconnect_fee_in_12m_net, disconnect_fee_after_12m_net,
  bucket_hint, quote_only, active,
  source_document, source_page, source_section, notes
)
SELECT g.id, x.ext_id, x.product_name, x.service_type, x.technology, x.network,
       x.dl_label, x.ul_label, x.dl_mbps, x.ul_mbps,
       x.term, x.monthly, x.conn_fee, x.etf,
       x.df12, x.dfaft,
       x.bucket, x.quote_only, false,
       'giacom_broadband_ratecard_v3.8.1', x.page, x.section, x.notes
